alter table public.finance_transactions add constraint finance_category_class check(category is null or (financial_class is not null and ((financial_class='revenue' and category in ('merchandise_sales','student_dues','fundraising_revenue','sponsorship_revenue','event_revenue','other_revenue')) or (financial_class='expense' and category in ('tournament_fees','event_fees','travel_expenses','lodging_expenses','meal_expenses','merchandise_expenses','equipment_supplies','software_subscriptions','printing_materials','other_expenses')) or (financial_class='asset' and category in ('cash','accounts_receivable','inventory','prepaid_expenses','equipment_assets')) or (financial_class='liability' and category in ('accounts_payable','student_refunds_payable','loans_payable','deferred_revenue','other_liabilities')) or (financial_class='cash_flow' and category in ('account_transfers','bank_deposits','cash_withdrawals','loan_proceeds','loan_repayments','opening_balance_adjustment')) or (financial_class='purchase_order' and category in ('outstanding_purchase_orders')))));
alter table public.finance_files add constraint finance_source_path check(object_path=group_id::text || '/' || id::text || '/source');
alter table public.finance_files add constraint finance_source_actor check(uploaded_by is not null);
-- Explicit least-privilege grants, independent of Supabase default privileges.
revoke all on public.finance_groups,public.finance_members,public.finance_sheets,public.finance_files,public.finance_transactions,public.finance_sheet_versions from anon,authenticated;
grant select on public.finance_groups,public.finance_members to authenticated;
grant select,insert,update on public.finance_sheets,public.finance_files,public.finance_transactions to authenticated;
grant select,insert on public.finance_sheet_versions to authenticated;
